content.text:
    s->p = 0;
    (void)c;
}

static slot_t *slot_find(const collector_t *c, uint32_t p)
{
    slot_t *s = &c->slots[p % c->N];
    if (s->used && s->p == p) {
        return s;
    }
    return NULL;
}

static slot_t *slot_create(collector_t *c, uint32_t p)
{
    slot_t *s = &c->slots[p % c->N];
    if (s->used) {
        /* Never expected: retained identities are logical, not p mod N. */
        c->st[30]++;
        slot_release(c, s);
        c->occupied--;
    }
    s->used = 1;
    s->p = p;
    s->mask = 0;
    s->complete = 0;
    c->occupied++;
    return s;
}

static void slot_store(collector_t *c, slot_t *s, int rank, const uint8_t *payload)
{
    size_t bytes = (size_t)c->D * 4u;
    if (c->primitive == EPIC_PRIM_ALLGATHER) {
        if (!s->raw[rank]) {
            s->raw[rank] = malloc(bytes ? bytes : 1u);
        }
        if (bytes) {
            memcpy(s->raw[rank], payload, bytes);
        }
        return;
    }
    if (c->primitive == EPIC_PRIM_BCAST) {
        int root = c->root;
        if (!s->raw[root]) {
            s->raw[root] = malloc(bytes ? bytes : 1u);
        }
        if (bytes) {
            memcpy(s->raw[root], payload, bytes);
        }
        return;
    }
    if (!s->agg) {
        s->agg = calloc(c->D ? c->D : 1u, sizeof(uint32_t));
    }
    if (c->D) {
        for (uint32_t j = 0; j < c->D; j++) {
            uint32_t v;
            memcpy(&v, payload + 4u * j, 4u);
            v = ntohl(v);
            s->agg[j] += v;
        }
    }
}

