typedef struct {
    int is_data;
    uint32_t psn;
    uint32_t qpn;
    uint32_t src_ip;
    uint32_t dst_ip;
    const uint8_t *payload;
    size_t payload_len;
} packet_t;

static int ipv4_checksum_ok(const uint8_t *ip)
{
    uint32_t sum = 0;
    for (int i = 0; i < 20; i += 2) {
        sum += ((uint32_t)ip[i] << 8) | (uint32_t)ip[i + 1];
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return (uint16_t)(~sum) == 0u;
}

